/**
 * PluginSDK - 插件SDK系统
 * 基于 nanobot SDK 架构
 * 插件注册/生命周期管理/沙箱环境/事件系统
 */

// 存储键
const SDK_PLUGINS_KEY = 'ai-creator-sdk-plugins';
const SDK_CONFIG_KEY = 'ai-creator-sdk-config';

// 插件状态
export const PluginStatus = {
  UNINSTALLED: 'uninstalled',
  INSTALLED: 'installed',
  ENABLED: 'enabled',
  DISABLED: 'disabled',
  ERROR: 'error'
};

// 插件类型
export const PluginType = {
  TOOL: 'tool',
  PANEL: 'panel',
  SERVICE: 'service',
  THEME: 'theme',
  EXTENSION: 'extension'
};

// 默认SDK配置
const DEFAULT_SDK_CONFIG = {
  sandboxEnabled: true,
  autoUpdate: false,
  devMode: false,
  maxPlugins: 50,
  permissions: {
    network: false,
    storage: true,
    clipboard: true,
    notifications: true
  }
};

// ============ 插件注册表 ============

/**
 * 获取所有已注册插件
 */
export function getRegisteredPlugins() {
  try {
    const stored = localStorage.getItem(SDK_PLUGINS_KEY);
    if (!stored) return {};
    return JSON.parse(stored);
  } catch {
    return {};
  }
}

/**
 * 保存插件注册表
 */
function savePlugins(plugins) {
  try {
    localStorage.setItem(SDK_PLUGINS_KEY, JSON.stringify(plugins));
  } catch {}
}

// ============ 内置插件 ============

/**
 * 注册内置插件
 */
export function registerBuiltinPlugin(pluginDef) {
  const plugins = getRegisteredPlugins();
  
  plugins[pluginDef.id] = {
    ...pluginDef,
    type: pluginDef.type || PluginType.EXTENSION,
    status: PluginStatus.ENABLED,
    builtin: true,
    installedAt: plugins[pluginDef.id]?.installedAt || Date.now()
  };
  
  savePlugins(plugins);
  return plugins[pluginDef.id];
}

/**
 * 初始化内置插件
 */
export function initBuiltinPlugins() {
  // 注册内置插件定义
  const builtinPlugins = [
    {
      id: 'sdk-core',
      name: 'SDK核心',
      version: '1.0.0',
      description: '提供SDK核心API',
      author: 'system',
      type: PluginType.SERVICE
    }
  ];
  
  for (const p of builtinPlugins) {
    registerBuiltinPlugin(p);
  }
}

// ============ 插件生命周期 ============

/**
 * 安装插件
 */
export function installPlugin(pluginDef) {
  const plugins = getRegisteredPlugins();
  
  if (plugins[pluginDef.id]) {
    return { success: false, error: 'Plugin already installed' };
  }
  
  plugins[pluginDef.id] = {
    ...pluginDef,
    status: PluginStatus.ENABLED,
    builtin: false,
    installedAt: Date.now()
  };
  
  savePlugins(plugins);
  
  return { success: true, plugin: plugins[pluginDef.id] };
}

/**
 * 卸载插件
 */
export function uninstallPlugin(pluginId) {
  const plugins = getRegisteredPlugins();
  
  if (!plugins[pluginId]) {
    return { success: false, error: 'Plugin not found' };
  }
  
  if (plugins[pluginId].builtin) {
    return { success: false, error: 'Cannot uninstall builtin plugin' };
  }
  
  delete plugins[pluginId];
  savePlugins(plugins);
  
  return { success: true };
}

/**
 * 启用插件
 */
export function enablePlugin(pluginId) {
  const plugins = getRegisteredPlugins();
  
  if (!plugins[pluginId]) {
    return { success: false, error: 'Plugin not found' };
  }
  
  plugins[pluginId].status = PluginStatus.ENABLED;
  savePlugins(plugins);
  
  return { success: true };
}

/**
 * 禁用插件
 */
export function disablePlugin(pluginId) {
  const plugins = getRegisteredPlugins();
  
  if (!plugins[pluginId]) {
    return { success: false, error: 'Plugin not found' };
  }
  
  plugins[pluginId].status = PluginStatus.DISABLED;
  savePlugins(plugins);
  
  return { success: true };
}

/**
 * 获取插件
 */
export function getPlugin(pluginId) {
  const plugins = getRegisteredPlugins();
  return plugins[pluginId] || null;
}

/**
 * 获取所有启用的插件
 */
export function getEnabledPlugins() {
  const plugins = getRegisteredPlugins();
  return Object.values(plugins).filter(p => p.status === PluginStatus.ENABLED);
}

// ============ SDK配置 ============

/**
 * 获取SDK配置
 */
export function getSDKConfig() {
  try {
    const stored = localStorage.getItem(SDK_CONFIG_KEY);
    if (!stored) return { ...DEFAULT_SDK_CONFIG };
    return { ...DEFAULT_SDK_CONFIG, ...JSON.parse(stored) };
  } catch {
    return { ...DEFAULT_SDK_CONFIG };
  }
}

/**
 * 更新SDK配置
 */
export function updateSDKConfig(updates) {
  const config = getSDKConfig();
  const merged = { ...config, ...updates };
  
  try {
    localStorage.setItem(SDK_CONFIG_KEY, JSON.stringify(merged));
  } catch {}
  
  return merged;
}

// ============ 插件沙箱 ============

/**
 * 创建插件沙箱环境
 */
export function createPluginSandbox(pluginId) {
  const config = getSDKConfig();
  
  if (!config.sandboxEnabled) {
    return null;
  }
  
  // 沙箱API白名单
  const sandboxAPI = {
    // 工具API
    tool: {
      list: () => getEnabledPlugins().filter(p => p.type === PluginType.TOOL),
      get: (id) => getPlugin(id),
      create: (def) => registerBuiltinPlugin({ ...def, id: pluginId + '-' + def.id }),
      invoke: (id, method, ...args) => {
        const plugin = getPlugin(id);
        if (plugin?.api?.[method]) {
          return plugin.api[method](...args);
        }
        throw new Error(`Method ${method} not found`);
      }
    },
    
    // 存储API
    storage: {
      get: (key) => {
        if (!config.permissions.storage) throw new Error('Storage permission denied');
        return localStorage.getItem(`plugin:${pluginId}:${key}`);
      },
      set: (key, value) => {
        if (!config.permissions.storage) throw new Error('Storage permission denied');
        localStorage.setItem(`plugin:${pluginId}:${key}`, value);
      },
      remove: (key) => {
        if (!config.permissions.storage) throw new Error('Storage permission denied');
        localStorage.removeItem(`plugin:${pluginId}:${key}`);
      }
    },
    
    // 剪贴板API
    clipboard: {
      read: () => {
        if (!config.permissions.clipboard) throw new Error('Clipboard permission denied');
        return navigator.clipboard.readText();
      },
      write: (text) => {
        if (!config.permissions.clipboard) throw new Error('Clipboard permission denied');
        return navigator.clipboard.writeText(text);
      }
    },
    
    // 事件API
    event: {
      on: (event, callback) => eventBus.on(pluginId, event, callback),
      off: (event, callback) => eventBus.off(pluginId, event, callback),
      emit: (event, data) => eventBus.emit(pluginId, event, data)
    },
    
    // 工具箱API
    panel: {
      registerButton: (button) => {
        const toolPanel = window.__toolPanel;
        if (toolPanel) {
          toolPanel.registerPluginButton(pluginId, button);
        }
      },
      unregisterButton: (buttonId) => {
        const toolPanel = window.__toolPanel;
        if (toolPanel) {
          toolPanel.unregisterPluginButton(pluginId, buttonId);
        }
      }
    },
    
    // 配置API
    config: {
      get: () => getSDKConfig(),
      update: (updates) => updateSDKConfig(updates)
    }
  };
  
  return sandboxAPI;
}

// ============ 事件总线 ============

const eventBus = {
  listeners: {},
  
  on(pluginId, event, callback) {
    const key = `${pluginId}:${event}`;
    if (!this.listeners[key]) {
      this.listeners[key] = [];
    }
    this.listeners[key].push(callback);
  },
  
  off(pluginId, event, callback) {
    const key = `${pluginId}:${event}`;
    if (this.listeners[key]) {
      if (callback) {
        this.listeners[key] = this.listeners[key].filter(cb => cb !== callback);
      } else {
        delete this.listeners[key];
      }
    }
  },
  
  emit(pluginId, event, data) {
    const key = `${pluginId}:${event}`;
    if (this.listeners[key]) {
      this.listeners[key].forEach(cb => {
        try {
          cb(data);
        } catch (e) {
          console.error(`Event handler error in ${pluginId}:${event}`, e);
        }
      });
    }
  },
  
  // 全局事件
  onGlobal(event, callback) {
    if (!this.listeners[`__global:${event}`]) {
      this.listeners[`__global:${event}`] = [];
    }
    this.listeners[`__global:${event}`].push(callback);
  },
  
  offGlobal(event, callback) {
    const key = `__global:${event}`;
    if (this.listeners[key]) {
      if (callback) {
        this.listeners[key] = this.listeners[key].filter(cb => cb !== callback);
      } else {
        delete this.listeners[key];
      }
    }
  },
  
  emitGlobal(event, data) {
    const key = `__global:${event}`;
    if (this.listeners[key]) {
      this.listeners[key].forEach(cb => {
        try {
          cb(data);
        } catch (e) {
          console.error(`Global event handler error: ${event}`, e);
        }
      });
    }
  }
};

export { eventBus };

// ============ 插件加载器 ============

/**
 * 加载插件脚本
 */
export async function loadPluginScript(pluginId, scriptUrl) {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = scriptUrl;
    script.async = true;
    
    script.onload = () => resolve();
    script.onerror = () => reject(new Error(`Failed to load plugin script: ${scriptUrl}`));
    
    document.head.appendChild(script);
  });
}

/**
 * 初始化SDK
 */
export function initPluginSDK() {
  initBuiltinPlugins();
  
  const config = getSDKConfig();
  if (config.devMode) {
    console.log('[PluginSDK] SDK initialized in dev mode');
  }
  
  return {
    version: '1.0.0',
    plugins: getRegisteredPlugins(),
    config
  };
}

export default {
  PluginStatus,
  PluginType,
  getRegisteredPlugins,
  registerBuiltinPlugin,
  initBuiltinPlugins,
  installPlugin,
  uninstallPlugin,
  enablePlugin,
  disablePlugin,
  getPlugin,
  getEnabledPlugins,
  getSDKConfig,
  updateSDKConfig,
  createPluginSandbox,
  eventBus,
  loadPluginScript,
  initPluginSDK
};